export const PROFILE_VERSION='6.0.0';
export const fieldGroups=[{id:'create',title:'Create, discover & build',families:['creative','technology','science','building','trades']},{id:'people',title:'People & communities',families:['health','education','public-safety','services']},{id:'everyday',title:'Business, systems & everyday life',families:['business','transportation-production','sales-office']}];
