export const contextQuestions=[
 {id:'company',prompt:'Who would you enjoy working alongside?',options:[['team','A close team'],['independent','Mostly on my own'],['mix','A mix of both'],['unknown','Still exploring']]},
 {id:'rhythm',prompt:'What would make a good working day?',options:[['variety','Different problems and changing tasks'],['routine','A steady rhythm and clear routines'],['mix','Some of each'],['unknown','Still exploring']]},
 {id:'setting',prompt:'Where could you picture spending your day?',multi:true,options:[['people','With people and communities'],['desk','With ideas, information, or digital tools'],['active','Making, moving, or working outdoors'],['unknown','I want to try a few settings']]},
 {id:'education',prompt:'Which learning routes would you consider?',multi:true,options:[['college','A college degree'],['graduate','College, then professional or graduate study'],['training','Paid training or a practical qualification'],['unknown','I want to learn about all of them']]}
];
export const profileQuestions=[...profileInterestQuestions.map(q=>({...q,prompt:q.text,kind:'interest',section:'Your interests · O*NET® Short Form'})),...pathwayProfileQuestions,...skillQuestions.map(q=>({...q,kind:'skill',section:'Strength clues'})),{id:'values',kind:'values',prompt:'What would you most want your work to give you?',section:'What matters to you'},...contextQuestions.map(q=>({...q,kind:'context',section:'Your working life'}))];
const familyIds=new Set(['creative','technology','health','business','science','building','trades','services','education','public-safety','transportation-production','sales-office']),values=new Set(priorities.map(p=>p.id));
// Presentation order only. Answers and scoring always use stable question IDs.
const questionById=new Map(profileQuestions.map(q=>[q.id,q]));
const sectionOf=q=>q.kind==='interest'?0:q.kind==='pathway'?1:q.kind==='skill'?2:q.kind==='values'?3:4;
const shuffle=(items,random)=>{const a=[...items];for(let i=a.length-1;i>0;i--){const j=Math.floor(random()*(i+1));[a[i],a[j]]=[a[j],a[i]];}return a;};
export function createProfileQuestionOrder(random=Math.random){
 const balanced=(items,key)=>{const groups=[...new Set(items.map(key))].map(k=>items.filter(q=>key(q)===k)),out=[];let last='';while(groups.some(g=>g.length)){const available=shuffle(groups.filter(g=>g.length),random);if(available.length>1&&key(available[0][0])===last)[available[0],available[1]]=[available[1],available[0]];for(const g of available){const q=g.shift();out.push(q);last=key(q);}}return out;};
 return [...profileQuestions.filter(q=>q.kind==='interest'),...balanced(profileQuestions.filter(q=>q.kind==='pathway'),q=>q.family),...shuffle(profileQuestions.filter(q=>q.kind==='skill'),random),...profileQuestions.filter(q=>['values','context'].includes(q.kind))].map(q=>q.id);
}
export function validProfileQuestionOrder(order){return Array.isArray(order)&&order.length===profileQuestions.length&&new Set(order).size===profileQuestions.length&&order.every((id,i)=>questionById.has(id)&&sectionOf(questionById.get(id))===sectionOf(profileQuestions[i]))&&order.slice(0,60).every((id,i)=>id===onetQuestions[i].id)&&Array.from({length:3},(_,i)=>new Set(order.slice(60+i*12,72+i*12).map(id=>questionById.get(id).family)).size===12).every(Boolean);}
export const orderedProfileQuestions=s=>validProfileQuestionOrder(s.profileJourney?.questionOrder)?s.profileJourney.questionOrder.map(id=>questionById.get(id)):profileQuestions;
export function ensureProfileQuestionOrder(s,random=Math.random){const j=s.profileJourney;if(!validProfileQuestionOrder(j.questionOrder))j.questionOrder=j.started?profileQuestions.map(q=>q.id):createProfileQuestionOrder(random);return orderedProfileQuestions(s);}

export const freshProfileJourney=()=>({version:PROFILE_VERSION,questionMode:'focused',reviewSection:'',introSeen:false,followupIntroSeen:false,sectionIntrosSeen:[],professionIntrosSeen:[],returnToField:false,started:false,index:0,questionOrder:[],broadRound:null,officialInterest:cleanOnetInterest(),legacyAssessment:null,interests:{},fieldPreferences:{},answers:{},skills:{},family:'',families:[],suggestedFamilies:[],depth:{},careerChecks:{},coreWork:{},expandedInterests:{},careerQuestionFeedback:{},depthIndexes:{},lastRoute:''});
export function cleanProfileJourney(raw){const j=freshProfileJourney();if(!raw||typeof raw!=='object')return j;const round=raw.broadRound;if(round?.version==='0.51.0'&&Array.isArray(round.questions)&&round.questions.length<=12&&round.questions.every(q=>typeof q?.careerId==='string'&&typeof q?.questionId==='string'&&/^[a-z0-9-]{1,120}$/.test(q.careerId)&&/^[a-z0-9-]{1,120}$/.test(q.questionId)))j.broadRound={version:'0.51.0',cursor:Number.isInteger(round.cursor)?Math.max(0,Math.min(round.questions.length,round.cursor)):0,questions:round.questions.map(q=>({careerId:q.careerId,questionId:q.questionId}))};j.coreWork=cleanCoreWork(raw.coreWork);j.expandedInterests=cleanExpandedInterests(raw.expandedInterests);j.careerChecks=cleanCareerChecks(raw.careerChecks);j.careerQuestionFeedback=cleanCareerQuestionFeedback(raw.careerQuestionFeedback);j.started=raw.started===true;j.reviewSection=['interest','pathway','skill','values','context'].includes(raw.reviewSection)?raw.reviewSection:'';j.introSeen=raw.introSeen===true;j.followupIntroSeen=raw.followupIntroSeen===true;j.sectionIntrosSeen=Array.isArray(raw.sectionIntrosSeen)?[...new Set(raw.sectionIntrosSeen.filter(k=>['skill','values','context'].includes(k)))]:[];j.officialInterest=cleanOnetInterest(raw.version==='6.0.0'?raw.officialInterest:null);j.professionIntrosSeen=Array.isArray(raw.professionIntrosSeen)?[...new Set(raw.professionIntrosSeen.filter(id=>familyIds.has(id)))]:[];j.returnToField=raw.returnToField===true;j.questionMode=raw.questionMode==='all'?'all':raw.questionMode==='focused'?'focused':raw.started?'all':'focused';const old=raw.version!=='6.0.0'&&raw.started?raw:raw.legacyAssessment;if(old&&typeof old==='object')j.legacyAssessment={version:String(old.version||'unknown').slice(0,20),index:Number.isInteger(old.index)?old.index:0,questionOrder:Array.isArray(old.questionOrder)?old.questionOrder.filter(id=>typeof id==='string'&&/^[a-z0-9-]+$/.test(id)).slice(0,113):[]};if(validProfileQuestionOrder(raw.questionOrder))j.questionOrder=[...raw.questionOrder];if(raw.version!=='6.0.0'&&Array.isArray(raw.questionOrder)){const migrated=[...onetQuestions.map(q=>q.id),...raw.questionOrder.slice(60)];if(validProfileQuestionOrder(migrated))j.questionOrder=migrated;}for(const q of additionalInterestQuestions){const v=raw.interests?.[q.id];if([1,2,3,4,5,'untried'].includes(v))j.interests[q.id]=v;}for(const q of pathwayProfileQuestions){const v=raw.fieldPreferences?.[q.id];if([1,2,3,4,5,'untried'].includes(v))j.fieldPreferences[q.id]=v;}j.index=Number.isInteger(raw.index)?Math.max(0,Math.min(profileQuestions.length-1,raw.index)):0;if(raw.version!=='6.0.0'&&raw.started)j.index=0;for(const q of contextQuestions){const allowed=new Set(q.options.map(o=>o[0])),a=raw.answers?.[q.id];if(q.multi&&Array.isArray(a))j.answers[q.id]=[...new Set(a.filter(v=>allowed.has(v)))];else if(!q.multi&&allowed.has(a))j.answers[q.id]=a;}for(const id of ['values','evidence'])if(raw.answers?.[id]===true)j.answers[id]=true;for(const q of skillQuestions){const a=raw.skills?.[q.id];if(!a||typeof a!=='object')continue;j.skills[q.id]={};if(validSkillLevel(a.level))j.skills[q.id].level=a.level;if(['new','some','often','unknown'].includes(a.practice))j.skills[q.id].practice=a.practice;if([1,2,3,4,5,'unknown'].includes(a.confidence))j.skills[q.id].confidence=a.confidence;}if(familyIds.has(raw.family))j.family=raw.family;j.families=Array.isArray(raw.families)?[...new Set(raw.families.filter(f=>familyIds.has(f)))].slice(0,3):[];j.suggestedFamilies=Array.isArray(raw.suggestedFamilies)?[...new Set(raw.suggestedFamilies.filter(f=>familyIds.has(f)))].slice(0,3):[];for(const f of careerFamilies){const qs=professionQuestions[f.id]||[],entry=raw.depth?.[f.id];if(entry&&typeof entry==='object'){j.depth[f.id]={};for(const q of qs){const a=entry[q.id],allowed=new Set(q.options.map(o=>o.id));if(Array.isArray(a))j.depth[f.id][q.id]=[...new Set(a.filter(v=>allowed.has(v)))];}}if(Number.isInteger(raw.depthIndexes?.[f.id]))j.depthIndexes[f.id]=Math.max(0,Math.min(qs.length-1,raw.depthIndexes[f.id]));}if(typeof raw.lastRoute==='string'&&/^journey\/[a-z0-9/-]+$/.test(raw.lastRoute))j.lastRoute=raw.lastRoute;if(raw.followupIntroSeen===undefined&&profileQuestions.some(q=>q.kind!=='interest'&&questionAnswered({profileJourney:j},q)))j.followupIntroSeen=true;return j;}
export function questionAnswered(s,q){const j=s.profileJourney||freshProfileJourney();if(q.kind==='pathway')return [1,2,3,4,5,'untried'].includes(j.fieldPreferences[q.id]);if(q.kind==='interest')return validOnetAnswer(profileInterestAnswer(s,q));if(q.kind==='skill'){const a=j.skills[q.id];return validSkillLevel(a?.level)||legacySkillComplete(a);}if(q.kind==='values'||q.kind==='evidence')return j.answers[q.id]===true;return q.multi?Array.isArray(j.answers[q.id])&&j.answers[q.id].length>0:q.options.some(([v])=>v===j.answers[q.id]);}
// The official instrument remains intact. Optional experience/work-style answers
// remain saved and can refine explanations without blocking a first result.
export function profileQuestionRequired(s,q){
 if(s.profileJourney?.questionMode==='all')return true;
 if(q.kind==='skill')return false;
 if(q.kind==='context')return q.id==='education';
 if(q.kind!=='pathway')return true;
 if(q.facet==='activity')return true;
 if(q.facet==='routine')return false;
 if(q.family===s.profileJourney?.family)return true;
 const first=pathwayProfileQuestions.find(x=>x.family===q.family&&x.facet==='activity');
 if(s.profileJourney?.fieldPreferences?.[first.id]>=4)return true;
 const p=journeyInterestPicture(s);if(!p.complete)return true;if(p.flat||p.nearFlat)return false;
 const values=fieldCareers(q.family).map(o=>careerInterestMatch(s,o,p)).filter(m=>m.r!==null).sort((a,b)=>b.r-a.r).slice(0,3);
 return values.length>0&&values.reduce((n,m)=>n+m.r,0)/values.length>=.608;
}
export const requiredProfileQuestions=s=>orderedProfileQuestions(s).filter(q=>profileQuestionRequired(s,q));
export const profileNavigationQuestions=s=>orderedProfileQuestions(s).filter(q=>s.profileJourney?.reviewSection?q.kind===s.profileJourney.reviewSection:profileQuestionRequired(s,q));
export const profileComplete=s=>requiredProfileQuestions(s).every(q=>questionAnswered(s,q));
const navigable=(s,q)=>s.profileJourney?.reviewSection?q.kind===s.profileJourney.reviewSection:profileQuestionRequired(s,q);
export function nextProfileIndex(s,from=-1,back=false){const qs=orderedProfileQuestions(s);for(let i=from+(back?-1:1);i>=0&&i<qs.length;i+=back?-1:1)if(navigable(s,qs[i]))return i;return -1;}
export const firstUnansweredProfileIndex=s=>orderedProfileQuestions(s).findIndex(q=>profileQuestionRequired(s,q)&&!questionAnswered(s,q));
export const lifestyleComplete=s=>s.guide?.lifestyleBuilder?.complete===true&&builderReady(s.guide.lifestyleBuilder);
export const profileIntroNeeded=s=>!s.profileJourney?.introSeen&&!profileQuestions.some(q=>questionAnswered(s,q));
export const officialSectionComplete=s=>profileQuestions.filter(q=>q.kind==='interest').every(q=>questionAnswered(s,q));
export const followupIntroNeeded=s=>!s.profileJourney?.followupIntroSeen&&s.profileJourney?.index>=onetQuestions.length&&officialSectionComplete(s)&&!profileQuestions.some(q=>q.kind!=='interest'&&questionAnswered(s,q));
export const profileSectionIntroRoute=kind=>kind==='skill'?'journey/profile-experience':kind==='values'?'journey/profile-priorities':kind==='context'?'journey/profile-working-life':'';
export function profileSectionReady(s,kind){const qs=orderedProfileQuestions(s),first=qs.findIndex(q=>q.kind===kind&&navigable(s,q));return first>=0&&qs.slice(0,first).filter(q=>profileQuestionRequired(s,q)).every(q=>questionAnswered(s,q));}
export function pendingProfileSectionIntro(s){const kind=orderedProfileQuestions(s)[s.profileJourney?.index]?.kind;if(!profileSectionIntroRoute(kind)||s.profileJourney.sectionIntrosSeen?.includes(kind)||!profileSectionReady(s,kind))return '';if(profileQuestions.some(q=>q.kind===kind&&questionAnswered(s,q))||kind==='values'&&s.priorities.length)return '';return profileSectionIntroRoute(kind);}
export const profileStartRoute=s=>profileIntroNeeded(s)?'journey/profile-intro':followupIntroNeeded(s)?'journey/profile-followups':pendingProfileSectionIntro(s)||'journey/profile';
export function beginProfileSection(s,kind){if(!profileSectionIntroRoute(kind)||!profileSectionReady(s,kind))return profileStartRoute(s);const j=s.profileJourney;j.sectionIntrosSeen??=[];if(!j.sectionIntrosSeen.includes(kind))j.sectionIntrosSeen.push(kind);const qs=orderedProfileQuestions(s);if(qs[j.index]?.kind!==kind)j.index=qs.findIndex(q=>q.kind===kind&&navigable(s,q));return 'journey/profile';}
export function backFromProfileSection(s,kind){if(s.profileJourney.reviewSection===kind){s.profileJourney.reviewSection='';return 'journey/profile-review';}if(!profileSectionIntroRoute(kind))return 'journey/profile';const first=orderedProfileQuestions(s).findIndex(q=>q.kind===kind);s.profileJourney.index=Math.max(0,nextProfileIndex(s,first,true));return 'journey/profile';}
export function profileSectionBackRoute(s){const qs=orderedProfileQuestions(s),kind=qs[s.profileJourney.index]?.kind;return qs.findIndex(q=>q.kind===kind&&navigable(s,q))===s.profileJourney.index?pendingProfileSectionIntro(s):'';}

export function beginProfileFollowups(s){if(!officialSectionComplete(s))return profileStartRoute(s);s.profileJourney.followupIntroSeen=true;if(s.profileJourney.index<onetQuestions.length)s.profileJourney.index=nextProfileIndex(s,onetQuestions.length-1);return 'journey/profile';}
export function backFromProfileFollowups(s){s.profileJourney.index=onetQuestions.length-1;return 'journey/profile';}
export function professionIntroNeeded(s){const j=s.profileJourney,family=j?.family,qs=professionQuestions[family];return familyIds.has(family)&&!!qs?.length&&!j.professionIntrosSeen?.includes(family)&&!qs.some(q=>Array.isArray(j.depth?.[family]?.[q.id]));}
export const professionStartRoute=s=>professionIntroNeeded(s)?'journey/profession-intro':'journey/deeper';
export function beginProfessionFollowups(s){if(!lifestyleComplete(s))return 'journey/lifestyle';if(!profileComplete(s))return profileStartRoute(s);const j=s.profileJourney;if(!familyIds.has(j.family))return 'journey/pathways';j.professionIntrosSeen??=[];if(!j.professionIntrosSeen.includes(j.family))j.professionIntrosSeen.push(j.family);return 'journey/deeper';}
export function beginProfileReview(s,index){const qs=orderedProfileQuestions(s),q=qs[index];if(!q||!profileSectionStarts().includes(index)||!profileComplete(s))return false;s.profileJourney.reviewSection=q.kind;s.profileJourney.index=index;return true;}
export function finishProfileReview(s){s.profileJourney.reviewSection='';if(profileComplete(s))return 'journey/profile-review';s.profileJourney.index=firstUnansweredProfileIndex(s);return profileStartRoute(s);}
export function profileResume(s){if(!lifestyleComplete(s))return 'journey/lifestyle';if(!profileComplete(s))return profileStartRoute(s);if(s.profileJourney?.reviewSection)return profileStartRoute(s);const last=s.profileJourney?.lastRoute;if(last&&/^journey\/(?:degree-check\/degree-[a-z0-9-]+|expanded-matches)$/.test(last))return last;if(s.profileJourney?.family&&last&&/^journey\/(deeper|profession-intro|professions|profession\/[a-z0-9-]+|check-career\/[a-z0-9-]+\/(?:[0-9]+|summary))$/.test(last))return last==='journey/deeper'?professionStartRoute(s):last;return 'journey/pathways';}
export function resolveJourneyRoute(s,r){const aliases={'guide/lifestyle':'journey/lifestyle','guide/lifestyle-summary':'journey/lifestyle-summary','guide/assessment':'journey/profile','guide/assessment-results':'journey/pathways','guide/paths':'journey/pathways','guide/specialty':'journey/pathways','guide/work-fit':'journey/pathways','guide/careers':'journey/pathways','guide/income-goal':'journey/lifestyle'};let target=(r.startsWith('guide/career/')?'journey/profession/'+r.split('/')[2]:r.startsWith('career/')?'learn/career/'+r.split('/')[1]:aliases[r])||(r.startsWith('activity/')?'journey/profile':r);if(target==='plan'&&(!s.guide?.primaryCareer||s.guide.planMode==='exploration'))target=profileResume(s);if(target.startsWith('journey/')&&!['journey/lifestyle','journey/research'].includes(target)&&!lifestyleComplete(s))return 'journey/lifestyle';if(target.startsWith('journey/')&&!['journey/lifestyle','journey/lifestyle-summary','journey/profile','journey/profile-intro','journey/profile-followups','journey/profile-experience','journey/profile-priorities','journey/profile-working-life','journey/research'].includes(target)&&!profileComplete(s))return profileStartRoute(s);if(target==='journey/profile'&&!s.profileJourney?.reviewSection&&profileComplete(s)&&!profileQuestionRequired(s,orderedProfileQuestions(s)[s.profileJourney.index]))return 'journey/pathways';if(target==='journey/profile'&&(profileIntroNeeded(s)||followupIntroNeeded(s)||pendingProfileSectionIntro(s)))return profileStartRoute(s);if(target==='journey/profile-followups'&&!officialSectionComplete(s))return profileStartRoute(s);const sectionKind=target==='journey/profile-experience'?'skill':target==='journey/profile-priorities'?'values':target==='journey/profile-working-life'?'context':'';if(sectionKind&&!profileSectionReady(s,sectionKind))return profileStartRoute(s);if(['journey/deeper','journey/profession-intro','journey/professions'].includes(target)&&!s.profileJourney?.family)return 'journey/pathways';if(target==='journey/deeper'&&professionIntroNeeded(s))return 'journey/profession-intro';if(target==='journey/professions'&&!depthComplete(s))return professionStartRoute(s);return target;}
const reasonItems={creative:[3,9,15,27],technology:[8,26,12,7],health:[14,16,4,22],business:[5,23,29,18],science:[2,20,26,19],building:[1,25,7,26],trades:[13,7,25,1],services:[21,17,16,19],education:[22,4,10,28],'public-safety':[16,25,28],'transportation-production':[25,24,30,18],'sales-office':[17,18,23,12]};
export function broadReasons(s,id){return (reasonItems[id]||[]).map(n=>curiosity[n-1]).filter(q=>profileInterestAnswer(s,q)>=4).map(q=>q.text).slice(0,2);}
export function broadSuggestions(s){const p=journeyInterestPicture(s),ranked=careerFamilies.map(f=>({...f,connection:journeyFieldConnection(s,f.id,p)})).sort((a,b)=>Number(b.connection.supported)-Number(a.connection.supported)||Number(b.connection.focused.confirmed)-Number(a.connection.focused.confirmed)||b.connection.baseMatch.tier-a.connection.baseMatch.tier||a.connection.focused.concerns.length-b.connection.focused.concerns.length||b.connection.explorationScore-a.connection.explorationScore||a.id.localeCompare(b.id));const fields=ranked.filter(f=>f.connection.supported).slice(0,3).map(f=>({...f,supported:true,reasons:f.connection.reasons}));const workFields=p.complete&&!p.flat&&!p.nearFlat?ranked.filter(f=>!f.connection.interestSupported&&f.connection.focused.confirmed&&!f.connection.conflicting).slice(0,3):[];return {limited:!p.complete||p.flat||p.nearFlat,kind:p.kind,fields,workFields,ranked};}
export function fieldCareers(family){const f=careerFamilies.find(f=>f.id===family);return f?occupations.filter(o=>f.paths.some(p=>pathCareerIds(p).includes(o.id))):[];}
export function depthComplete(s,family=s.profileJourney?.family){return (professionQuestions[family]||[]).every(q=>Array.isArray(s.profileJourney?.depth?.[family]?.[q.id]));}
export function reportedStrengths(s,o){const names=new Set([...(occupationEssentials[o?.soc]?.skills||[]),...(occupationEssentials[o?.soc]?.abilities||[])].map(x=>x.name));return skillQuestions.filter(q=>skillExperienceFamiliar(s.profileJourney?.skills[q.id])&&q.names.some(n=>names.has(n)));}
// A transparent disagreement flag, not a validated fit category or ranking input.
export function occupationalInterestVector(o){const rows=occupationEssentials[o?.soc]?.interests||[];const vector=riasecOrder.map(t=>rows.find(x=>x.name===riasecNames[t])?.value);return vector.every(Number.isFinite)?vector:null;}
export function careerInterestMatch(s,o,p=journeyInterestPicture(s)){const vector=occupationalInterestVector(o),r=p.complete&&!p.flat&&vector?profileCorrelation(p.raw,vector):null,fit=interestFit(r),status=!p.complete?'incomplete':p.flat?'flat':!vector?'missing':'compared';return {...fit,status,r,vector,source:occupationEssentials[o?.soc]?.interests?.[0]?.date||null,eligible:status==='compared'&&!p.nearFlat&&fit.tier>=2};}
export function earlierInterestContrast(s,o,p=journeyInterestPicture(s)){const m=careerInterestMatch(s,o,p);return m.status==='compared'&&m.tier<2;}
// Shared task options can support several jobs. Prefer the role with additional,
// independent work evidence on the main cards; keep every supported alternative.
// This changes presentation prominence, never official scores or eligibility.
export function markSharedTaskAlternatives(rows){
 for(const row of rows){row.comparisonOnly=false;row.sharedTaskAlternatives=[];if(!row.supported)continue;
  const keys=new Set(row.evidence.map(e=>e.questionId+':'+e.id));
  for(const other of rows){if(other===row||!other.supported)continue;const otherKeys=new Set(other.evidence.map(e=>e.questionId+':'+e.id));
   if(keys.size>=otherKeys.size||![...keys].every(k=>otherKeys.has(k)))continue;
   const extra=other.evidence.filter(e=>e.scope<=2&&!keys.has(e.questionId+':'+e.id));
   if(new Set(extra.map(e=>e.questionId)).size>=2&&new Set(extra.map(e=>e.domain)).size>=2)row.sharedTaskAlternatives.push(other.o.id);
  }
  row.comparisonOnly=row.sharedTaskAlternatives.length>0;
  row.sharedWork=rows.some(other=>other!==row&&other.score>=3&&new Set(row.evidence.filter(e=>other.evidence.some(o=>o.questionId===e.questionId&&o.id===e.id)).map(e=>e.questionId)).size>=3); 
 }
 return rows;
}
export function professionSuggestions(s,family=s.profileJourney?.family){const answers=s.profileJourney?.depth?.[family]||{},qs=professionQuestions[family]||[],taskQs=qs.filter(q=>q.kind!=='route'),picture=journeyInterestPicture(s),related=journeyFieldConnection(s,family,picture),focusedRoles=new Set(qs.filter(q=>q.kind==='role-task').flatMap(q=>q.options.filter(o=>(answers[q.id]||[]).includes(o.id)).flatMap(o=>o.careerIds)));const rows=fieldCareers(family).map(o=>{const evidence=taskQs.flatMap(q=>q.options.filter(opt=>(answers[q.id]||[]).length<q.options.length&&(answers[q.id]||[]).includes(opt.id)&&opt.careerIds.includes(o.id)).map(opt=>({questionId:q.id,question:q.prompt,text:opt.text,id:opt.id,scope:opt.careerIds.length,kind:q.kind||'task',domain:taskEvidenceDomain(q)}))),domains=[...new Set(evidence.map(e=>e.domain))],score=new Set(evidence.map(e=>e.questionId)).size,refinementSupport=new Set(evidence.filter(e=>e.questionId.includes('-refine-')).map(e=>e.questionId)).size,focusedSupport=new Set(evidence.filter(e=>{const q=qs.find(q=>q.id===e.questionId);return (answers[q.id]||[]).length<=2&&(answers[q.id]||[]).length<q.options.length;}).map(e=>e.questionId)).size,roleEvidence=evidence.filter(e=>e.kind==='role-task'),specificSupport=new Set(roleEvidence.map(e=>e.questionId)).size,routeQs=qs.filter(q=>q.kind==='route'),routeEvidence=routeQs.flatMap(q=>q.options.filter(opt=>(answers[q.id]||[]).includes(opt.id))),routeSupport=routeEvidence.some(e=>e.careerIds.includes(o.id)),routeConflict=clinicalRoleIds.includes(o.id)&&routeEvidence.length>0&&!routeSupport,roleFocusElsewhere=family==='health'&&focusedRoles.size>0&&!focusedRoles.has(o.id),needsRoleDetail=family==='health'&&clinicalRoleIds.includes(o.id)&&specificSupport<2,interestMatch=careerInterestMatch(s,o,picture),fieldContrast=related.conflicting,taskSupported=picture.complete&&!picture.flat&&!picture.nearFlat&&related.focused.confirmed&&score>=6&&refinementSupport>=3&&focusedSupport>=4&&interestMatch.status==='compared',basis=interestMatch.eligible?'profile-and-tasks':taskSupported?'tasks':'explore';return {o,evidence,domains,score,refinementSupport,focusedSupport,taskSupported,basis,taskTotal:taskQs.length,roleEvidence,specificSupport,routeSupport,routeConflict,roleFocusElsewhere,needsRoleDetail,interestMatch,interestContrast:score>=3&&interestMatch.status==='compared'&&interestMatch.r<0,reasons:[...roleEvidence,...evidence.filter(e=>e.kind!=='role-task')].slice(0,3).map(e=>e.text),strengths:reportedStrengths(s,o),supported:score>=3&&domains.length>=2&&(interestMatch.eligible||taskSupported)&&!fieldContrast&&!routeConflict&&!needsRoleDetail&&!roleFocusElsewhere,fieldContrast,broad:related};}).sort((a,b)=>b.specificSupport-a.specificSupport||Number(b.routeSupport)-Number(a.routeSupport)||b.score-a.score||(b.interestMatch.r??-2)-(a.interestMatch.r??-2)||a.o.id.localeCompare(b.o.id));markSharedTaskAlternatives(rows);const complete=depthComplete(s,family),uninformative=taskQs.length>0&&taskQs.every(q=>Array.isArray(answers[q.id])&&answers[q.id].length===q.options.length),supported=rows.filter(r=>r.supported&&!r.comparisonOnly),top=[];let unresolvedTie=false;const keyFor=r=>[r.specificSupport,Number(r.routeSupport),r.score].join(':');for(const key of [...new Set(supported.map(keyFor))]){const tier=supported.filter(r=>keyFor(r)===key);if(top.length+tier.length>3){unresolvedTie=true;break;}top.push(...tier);}const status=!complete?'incomplete':uninformative?'broad':!picture.complete?'assessment-needed':picture.flat||picture.nearFlat?'open-profile':related.conflicting?'preference-conflict':unresolvedTie&&!top.length?'broad':!supported.length?'no-clues':'suggestions';const taskLeads=complete&&!uninformative?rows.filter(r=>r.score>=6&&!r.supported&&!r.fieldContrast&&!r.routeConflict&&!r.roleFocusElsewhere&&!r.needsRoleDetail).slice(0,3):[];return {rows,taskLeads,top:complete&&!uninformative?top:[],limited:!complete||uninformative||!top.length,status,unresolvedTie,supportedCount:rows.filter(r=>r.supported).length,sharedTaskAlternativeCount:rows.filter(r=>r.comparisonOnly).length};}
export function saveProfileAnswer(s,q,value){const j=s.profileJourney;if(q.kind==='skill'){if(!skillQuestions.some(x=>x.id===q.id)||!validSkillLevel(value))return false;j.skills[q.id]={...j.skills[q.id],level:value};return true;}if(q.kind==='pathway'){if(![1,2,3,4,5,'untried'].includes(value))return false;j.fieldPreferences[q.id]=value;return true;}if(q.kind==='interest'){if(!onetQuestions.some(x=>x.id===q.id)||!validOnetAnswer(value))return false;j.officialInterest=cleanOnetInterest(j.officialInterest);j.officialInterest.answers[q.id]=value;return true;}if(q.kind==='context'&&!q.multi&&q.options.some(([v])=>v===value)){j.answers[q.id]=value;return true;}return false;}
export function advanceProfile(s){const j=s.profileJourney,next=nextProfileIndex(s,j.index);if(next<0){if(j.reviewSection)return finishProfileReview(s);if(profileComplete(s)){if(j.returnToField&&j.family){j.returnToField=false;return 'journey/deeper';}return 'journey/pathways';}j.index=firstUnansweredProfileIndex(s);return 'journey/profile';}const qs=orderedProfileQuestions(s),previousKind=qs[j.index]?.kind;j.index=next;const kind=qs[next]?.kind;if(previousKind==='interest'&&kind==='pathway'&&followupIntroNeeded(s))return 'journey/profile-followups';if(kind!==previousKind&&pendingProfileSectionIntro(s))return pendingProfileSectionIntro(s);return 'journey/profile';}

// One plan transition shared by the live guide and read-only walkthroughs.
export function makeJourneyPlan(s,id){if(!lifestyleComplete(s)||!profileComplete(s))return false;const o=occupationById(id);if(!o)return false;if(o.expandedDegree){rememberExploration(s);if(!selectCareer(s,id))return false;s.guide.salaryPicked=false;for(const [suffix,title,detail]of [['learn','Explore the work','Read the sourced examples and record what you want to understand.'],['prepare','Compare preparation routes','Verify an appropriate program, supervised preparation and any licensing.'],['talk','Ask about everyday work','Prepare questions for a counselor or a qualified professional.']]){const actionId='guide-'+id+'-'+suffix;if(!s.actions.some(a=>a.id===actionId))s.actions.push({id:actionId,careerId:id,title,detail,done:false,notice:''});}return true;}rememberExploration(s);const j=s.profileJourney;j.suggestedFamilies=broadSuggestions(s).fields.map(f=>f.id);const f=careerFamilies.find(f=>f.id===j.family&&f.paths.some(p=>o.pathIds.includes(p)))||careerFamilies.find(f=>f.paths.some(p=>o.pathIds.includes(p)));if(f){j.family=f.id;s.guide.familyIds=[f.id];s.guide.family=f.id;s.guide.pathIds=o.pathIds.filter(p=>f.paths.includes(p)).slice(0,3);s.guide.path=s.guide.pathIds[0]||'';}s.guide.taskInterests=['work:'+id];selectCareer(s,id);s.guide.salaryPicked=true;applyGuidePay(s);createPlanActions(s);return true;}

export const journeyInterestPicture=scoreOnetInterest;
export function journeyFieldConnection(s,id,picture){const p=picture||journeyInterestPicture(s),focused=pathwayProfileEvidence(s,id),seen=new Set(),rows=fieldCareers(id).map(o=>({o,match:careerInterestMatch(s,o,p)})).filter(x=>{if(x.match.r===null||seen.has(x.o.soc))return false;seen.add(x.o.soc);return true;}).sort((a,b)=>b.match.r-a.match.r),leading=rows.slice(0,3),mean=leading.length?leading.reduce((n,x)=>n+x.match.r,0)/leading.length:null,interestSupported=p.complete&&!p.flat&&!p.nearFlat&&mean!==null&&mean>=.608,conflicting=focused.concerns.length>=2,supported=interestSupported&&focused.confirmed&&!conflicting;const themes=[...riasecOrder].sort((a,b)=>(p.groups[b].raw??0)-(p.groups[a].raw??0)).slice(0,2),reasons=supported?['Across all six scores, this field has a strong interest connection.','Work you also liked: '+focused.likes.map(q=>q.summary).join(' · ')+'.']:[];return {supported,interestSupported,conflicting,score:mean??-1,explorationScore:mean??-1,focused,baseRoles:leading.map(x=>({id:x.o.id,title:x.o.title,r:x.match.r})),baseMatch:interestFit(mean),broadSupport:supported,activityIds:onetQuestions.filter(q=>themes.includes(q.theme)&&profileInterestAnswer(s,q)>=4).map(q=>q.id),themes,reasons};}
